using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Documents;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Navigation;
using System.Windows.Shapes;
using Syncfusion.Windows.Tools.Controls;
namespace NotifyIcon 
{
    /// 
    /// Interaction logic for Window1.xaml
    /// 
    public partial class Window1 : Window
    {
        public Window1()
        {
            InitializeComponent();
            NotifyIcon notifyIcon = new NotifyIcon();
            notifyIcon.BalloonTipText = "Custom Notify Icon is Available";
            notifyIcon.BalloonTipTitle = "Default NotifyIcon";
            notifyIcon.ShowBalloonTipTime = 1000;
            notifyIcon.HideBalloonTipTime = 1000;
            this.Content = notifyIcon;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Documents;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Navigation;
using System.Windows.Shapes;
using Syncfusion.Windows.Tools.Controls;
namespace TabControlExt
{
    /// 
    /// Interaction logic for Window1.xaml
    /// 
    public partial class Window1 : Window
    {
        public Window1()
        {
            InitializeComponent();
            // Creating instance of the TabControlExt control
            TabControlExt tabControlExt = new TabControlExt();
            // Creating the instance of StackPanel
            StackPanel stackPanel = new StackPanel();
            // Creating instance of the TabItemExt 
            TabItemExt tabItemExt1 = new TabItemExt();
            // Setting header of the TabItemExt
            tabItemExt1.Header = "TabItemExt";
            // Adding tabitemext to tabcontrolext
            tabControlExt.Items.Add(tabItemExt1);
            // Adding control to the stackpanel
            stackPanel.Children.Add(tabControlExt);
        }
    }
}

